178	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        currentOwner.setAddress(ownerFieldsDto.getAddress());
184	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
185	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
186	        applyAddress(currentOwner);
187	        currentOwner.setCity(ownerFieldsDto.getCity());
188	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
189	        currentOwner.setLastName(ownerFieldsDto.getLastName());
190	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
191	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
192	        this.clinicService.saveOwner(currentOwner);
193	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
194	    }
