273	    /**
274	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
275	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
276	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
277	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
278	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
279	     * sequence number, so its base form is a stable function of the owner's region and
280	     * telephone/last-name identity rather than of creation order.
281	     *
282	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
283	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
284	     * existing owner already has; the de-duplicated code is returned.
285	     *
286	     * @param owner the owner being created, with its telephone already normalized to E.164 form
287	     * @return the assigned, collision-free customer code
288	     */
289	    private String customerCodeFor(Owner owner) {
290	        String region = ownerMapper.regionOf(owner);
291	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
292	        String baseCode = region + "-" + hash8;
293	        if (!isCustomerCodeInUse(baseCode)) {
294	            return baseCode;
295	        }
296	        int n = 2;
297	        String candidate = baseCode + "-" + n;
298	        while (isCustomerCodeInUse(candidate)) {
299	            n++;
300	            candidate = baseCode + "-" + n;
301	        }
302	        return candidate;
303	    }
304	
305	    /**
306	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
307	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
308	     *
309	     * @param customerCode the candidate customer code to look for
310	     * @return {@code true} if an existing owner already has that customer code
311	     */
312	    private boolean isCustomerCodeInUse(String customerCode) {
313	        for (Owner existing : this.clinicService.findAllOwners()) {
314	            if (customerCode.equals(existing.getCustomerCode())) {
315	                return true;
316	            }
317	        }
318	        return false;
319	    }
320	
321	    /**
322	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
323	     * upper-case hex string.
324	     *
325	     * @param value the string to hash
326	     * @return the full SHA-256 digest as upper-case hex
327	     */
328	    private static String sha256UpperHex(String value) {
329	        try {
330	            byte[] digest = MessageDigest.getInstance("SHA-256")
331	                .digest(value.getBytes(StandardCharsets.UTF_8));
332	            StringBuilder sb = new StringBuilder(digest.length * 2);
333	            for (byte b : digest) {
334	                sb.append(String.format("%02X", b));
335	            }
336	            return sb.toString();
337	        } catch (NoSuchAlgorithmException ex) {
338	            throw new IllegalStateException("SHA-256 not available", ex);
339	        }
340	    }
341	
342	    /**
343	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
344	     * owner's city already contains this many owners.
345	     */
346	    private static final int CITY_CAPACITY = 50;
347	
348	    /**
349	     * The maximum number of owners that may be created on a single day. A create is rejected with
350	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
351	     * {@code registrationDate}.
352	     */
353	    private static final int DAILY_CREATE_LIMIT = 100;
354	
355	    /**
356	     * The number of owners that must already have been created for the current day before a new
357	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
358	     * owners already carry today's {@code registrationDate}.
359	     */
360	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
361	
362	    /**
363	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
364	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
365	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
366	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
367	     * falls on a business day.
368	     *
369	     * @param date the effective registration date
370	     * @return the same date when it is a weekday, otherwise the following Monday
371	     */
372	    private static LocalDate rollToBusinessDay(LocalDate date) {
373	        return switch (date.getDayOfWeek()) {
374	            case SATURDAY -> date.plusDays(2);
375	            case SUNDAY -> date.plusDays(1);
376	            default -> date;
377	        };
378	    }
379	
380	    /**
381	     * Counts the existing owners whose {@code registrationDate} equals the given (already
382	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
383	     * business day. Called before a new owner is saved, so the returned value reflects the number of
384	     * owners created for that day prior to this create.
385	     *
386	     * @param date the adjusted business-day registration date to count against
387	     * @return the number of existing owners registered on that date
388	     */
389	    private int countOwnersRegisteredOn(LocalDate date) {
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(existing -> date.equals(existing.getRegistrationDate()))
392	            .count();
393	    }
394	
395	    /**
396	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
397	     *
398	     * @param city the city to count owners for
399	     * @return the number of existing owners in that city
400	     */
401	    private int countOwnersInCity(String city) {
402	        return (int) this.clinicService.findAllOwners().stream()
403	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
404	            .count();
405	    }
406	
407	    /**
408	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
409	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
410	     *
411	     * @param customerCode     the owner's assigned customer code
412	     * @param registrationDate the owner's registration date
413	     * @return the assigned membership number
414	     */
415	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
416	        String yy = String.format("%02d", registrationDate.getYear() % 100);
417	        return String.format("%s-M%s", customerCode, yy);
418	    }
419	
420	    /**
421	     * Counts the existing owners that already share the given first name and last name, comparing
422	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
423	     * the number of namesakes that existed prior to this create.
424	     *
425	     * @param firstName the new owner's first name
426	     * @param lastName  the new owner's last name
427	     * @return the number of existing owners with the same first and last name
428	     */
429	    private int countNamesakes(String firstName, String lastName) {
430	        int count = 0;
431	        for (Owner existing : this.clinicService.findAllOwners()) {
432	            if (firstName.equalsIgnoreCase(existing.getFirstName())
433	                && lastName.equalsIgnoreCase(existing.getLastName())) {
434	                count++;
435	            }
436	        }
437	        return count;
438	    }
439	
440	    /**
441	     * Counts the existing owners that already belong to the given household (i.e. that share the
442	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
443	     * being created yields the household's total size at the moment of creation. Owners without a
444	     * household id are ignored.
445	     *
446	     * @param householdId the new owner's assigned household id
447	     * @return the number of existing owners already in that household
448	     */
449	    private int countHouseholdMembers(String householdId) {
450	        if (householdId == null) {
451	            return 0;
452	        }
453	        int count = 0;
454	        for (Owner existing : this.clinicService.findAllOwners()) {
455	            if (householdId.equals(existing.getHouseholdId())) {
456	                count++;
457	            }
458	        }
459	        return count;
460	    }
461	
462	    /**
463	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
464	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
465	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
466	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
467	     * string is what gets stored and returned.
468	     *
469	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
470	     *
471	     * <p>Once in E.164 form the national-number length is validated against the country code: a
472	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
473	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
474	     * rule are accepted on the general 8-to-15 digit length alone.
475	     *
476	     * @param telephone the raw telephone value supplied by the client
477	     * @return the normalized E.164 telephone number
478	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
479	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
480	     *                                 after the {@code '+'}, or the wrong national-number length for
481	     *                                 its country code)
482	     */
483	    private static String normalizeTelephone(String telephone) {
484	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
485	        String digits;
486	        if (cleaned.startsWith("+")) {
487	            digits = cleaned.substring(1);
488	        } else {
489	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
490	            digits = "61" + national;
491	        }
492	        if (!digits.matches("[0-9]{8,15}")) {
493	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
494	                "telephone could not be normalized to a valid E.164 number");
495	        }
496	        validateNationalNumberLength(digits);
497	        return "+" + digits;
498	    }
499	
500	    /**
501	     * Validates the national-number length of an E.164 number (its digits, without the leading
502	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
503	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
504	     * (only the general 8-to-15 digit rule applies).
505	     *
506	     * @param digits the E.164 digits without the leading {@code '+'}
507	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
508	     *                                 digits does not match the country code's required length
509	     */
510	    private static void validateNationalNumberLength(String digits) {
511	        E164PhoneNumbers.countryCode(digits)
512	            .ifPresent(code -> {
513	                int nationalLength = digits.length() - code.length();
514	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
515	                if (nationalLength != required) {
516	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
517	                        "telephone must have " + required
518	                            + " national digits for country code +" + code);
519	                }
520	            });
521	    }
522	
523	    /**
524	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
525	     * containing at least one dot, none of the three sections containing whitespace or an
526	     * additional {@code @}.
527	     */
528	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
529	
530	    /**
531	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
532	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
533	     * case-insensitively against the domain (the part after the {@code @}).
534	     */
535	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
536	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
537	
538	    /**
539	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
540	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
541	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
542	     * lower-cased.
543	     *
544	     * @param email the raw email value supplied by the client, possibly {@code null}
545	     * @return the lower-cased email, or {@code null} when none was supplied
546	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
547	     *                                 is not a syntactically valid address, or its domain is on the
548	     *                                 disposable-domain blocklist
549	     */
550	    private static String normalizeEmail(String email) {
551	        if (email == null) {
552	            return null;
553	        }
554	        if (!EMAIL_PATTERN.matcher(email).matches()) {
555	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
556	                "email must be a syntactically valid address");
557	        }
558	        String normalized = email.toLowerCase(Locale.ROOT);
559	        String domain = normalized.substring(normalized.indexOf('@') + 1);
560	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
561	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
562	                "email domain " + domain + " is not allowed");
563	        }
564	        return normalized;
565	    }
566	
567	    /**
568	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
569	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
570	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
571	     */
572	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
573	        "NSW", new int[] {2000, 2099},
574	        "VIC", new int[] {3000, 3099},
575	        "QLD", new int[] {4000, 4099});
576	
577	    /**
578	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
579	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
580	     * four-digit format is enforced by request validation; here the value is range-checked: when the
581	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
582	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
583	     * accepts any four-digit postcode.
584	     *
585	     * @param city     the owner's city
586	     * @param postcode the owner's postcode, possibly {@code null}
587	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
588	     *                                 out of range for the city's region
589	     */
590	    private static void validatePostcode(String city, String postcode) {
591	        if (postcode == null) {
592	            return;
593	        }
594	        String region = OwnerMapper.CITY_REGION.get(city);
595	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
596	        if (range == null) {
597	            return;
598	        }
599	        int value = Integer.parseInt(postcode);
600	        if (value < range[0] || value > range[1]) {
601	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
602	                "postcode " + postcode + " is not valid for region " + region);
603	        }
604	    }
605	
606	    /**
607	     * Common street-type abbreviations expanded to their full word during address normalization.
608	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
609	     */
610	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
611	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
612	
613	    /**
614	     * Applies an owner's address, accepting either the structured form (a non-blank
615	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
616	     * preferring the structured fields when present. Whichever fields are supplied are normalized
617	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
618	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
619	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
620	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
621	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
622	     * {@code address} (plus city) is still accepted.
623	     *
624	     * @param owner the owner being created or updated, carrying the raw address fields
625	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
626	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
627	     *                                 supplied
628	     */
629	    private static void applyAddress(Owner owner) {
630	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
631	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
632	        if (!hasStructured && !hasFlat) {
633	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
634	                "an address must be supplied, either 'addressLine1' or 'address'");
635	        }
636	        if (hasStructured) {
637	            String line1 = normalizeAddress(owner.getAddressLine1());
638	            owner.setAddressLine1(line1);
639	            String composed = line1;
640	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
641	                String line2 = normalizeAddress(owner.getAddressLine2());
642	                owner.setAddressLine2(line2);
643	                composed = line1 + " " + line2;
644	            } else {
645	                owner.setAddressLine2(null);
646	            }
647	            owner.setAddress(composed);
648	        } else {
649	            owner.setAddressLine1(null);
650	            owner.setAddressLine2(null);
651	            owner.setAddress(normalizeAddress(owner.getAddress()));
652	        }
653	    }
654	
655	    /**
656	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
657	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
658	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
659	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
660	     *
661	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
662	     *
663	     * @param address the raw address supplied by the client, possibly {@code null}
664	     * @return the normalized address
665	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
666	     *                                 after normalization (required field)
667	     */
668	    private static String normalizeAddress(String address) {
669	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
670	        if (collapsed.isEmpty()) {
671	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
672	                "address must not be blank");
673	        }
674	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
675	        StringBuilder normalized = new StringBuilder();
676	        for (int i = 0; i < tokens.length; i++) {
677	            if (i > 0) {
678	                normalized.append(' ');
679	            }
680	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
681	        }
682	        return normalized.toString();
683	    }
684	
685	    /**
686	     * Determines whether the given whole identity key already belongs to any owner other than the
687	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
688	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
689	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
690	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
691	     *
692	     * @param identityKey the identity key to look for
693	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
694	     * @return {@code true} if another owner already has the same identity key
695	     */
696	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
697	        for (Owner existing : this.clinicService.findAllOwners()) {
698	            if (excludeId != null && excludeId.equals(existing.getId())) {
699	                continue;
700	            }
701	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
702	                return true;
703	            }
704	        }
705	        return false;
706	    }
707	
708	    /**
709	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
710	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
711	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
712	     * (identical identity key) has already been rejected with a 409 before this runs, so this
713	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
714	     * so the result is deterministic when several owners qualify.
715	     *
716	     * @param owner the new owner being created, with its telephone already normalized
717	     * @return the matching existing owner, or {@code null} when none qualifies
718	     */
719	    private Owner findPossibleDuplicate(Owner owner) {
720	        if (owner.getLastName() == null || owner.getPostcode() == null) {
721	            return null;
722	        }
723	        return this.clinicService.findAllOwners().stream()
724	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
725	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
726	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
727	            .min(Comparator.comparingInt(Owner::getId))
728	            .orElse(null);
729	    }
730	
731	}
