53	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
54	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
55	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
56	     */
57	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
58	        LocalDate birthDate = owner.getBirthDate();
59	        if (birthDate == null) {
60	            return null;
61	        }
62	        LocalDate reference = owner.getRegistrationDate() != null
63	            ? owner.getRegistrationDate() : LocalDate.now();
64	        int age = Period.between(birthDate, reference).getYears();
65	        if (age < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (age < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
76	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
77	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
78	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
79	     *
80	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
81	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
82	     * code, a two-digit country code is assumed (the most common length).
83	     */
84	    default String toTelephoneDisplay(Owner owner) {
85	        String telephone = owner.getTelephone();
86	        if (telephone == null || !telephone.startsWith("+")) {
87	            return telephone;
88	        }
89	        String digits = telephone.substring(1);
90	        String code = E164PhoneNumbers.countryCode(digits)
91	            .filter(c -> digits.length() > c.length())
92	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
93	        String national = digits.substring(code.length());
94	        StringBuilder sb = new StringBuilder("+").append(code);
95	        for (int i = 0; i < national.length(); i += 3) {
96	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
97	        }
98	        return sb.toString();
99	    }
100	
101	    /**
102	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
103	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
104	     */
105	    default Integer toCheckDigit(Owner owner) {
106	        String code = owner.getCustomerCode();
107	        if (code == null) {
108	            return null;
109	        }
110	        int sum = 0;
111	        boolean dbl = true;
112	        for (int i = code.length() - 1; i >= 0; i--) {
113	            char c = code.charAt(i);
114	            if (c < '0' || c > '9') {
115	                continue;
116	            }
117	            int d = c - '0';
118	            if (dbl) {
119	                d *= 2;
120	                if (d > 9) {
121	                    d -= 9;
122	                }
123	            }
124	            sum += d;
125	            dbl = !dbl;
126	        }
127	        return (10 - (sum % 10)) % 10;
128	    }
129	
130	    /**
131	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
132	     * lower-cased email (empty when none), and the household id (empty when none), joined with
133	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
134	     *
135	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
136	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
137	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
138	     */
139	    default String toIdentityKey(Owner owner) {
140	        String email = hasEmail(owner) ? owner.getEmail() : "";
141	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
142	        return owner.getTelephone() + "|" + email + "|" + household;
143	    }
144	
145	    /**
146	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
147	     * for the "is an email present" rule shared by the derived fields below.
148	     */
149	    default boolean hasEmail(Owner owner) {
150	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
