169	    default Integer toMembershipPoints(Owner owner) {
170	        int points = 0;
171	        if (hasEmail(owner)) {
172	            points += 2;
173	        }
174	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
175	        if (noNamesakes) {
176	            points += 1;
177	        }
178	        if (hasHouseholdBonus(owner)) {
179	            points += 2;
180	        }
181	        if (hasTenureBonus(owner)) {
182	            points += 3;
183	        }
184	        return points;
185	    }
