187	    /**
188	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
189	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
190	     * Returns {@code false} when no household size is present (e.g. legacy records).
191	     */
192	    default boolean hasHouseholdBonus(Owner owner) {
193	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
194	    }
