196	    /**
197	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
198	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
199	     * or more.
200	     */
201	    default Integer toMembershipLevel(Owner owner) {
202	        int points = toMembershipPoints(owner);
203	        if (points <= 1) {
204	            return 1;
205	        }
206	        if (points <= 3) {
207	            return 2;
208	        }
209	        if (points <= 5) {
210	            return 3;
211	        }
212	        return 4;
213	    }
