215	    /**
216	     * Whether the owner's tenure exceeds 365 days, i.e. more than a year has elapsed between the
217	     * {@code registrationDate} and the current date. A brand-new owner (registered today) has zero
218	     * tenure and so never qualifies. Returns {@code false} when no registration date is present.
219	     */
220	    default boolean hasTenureBonus(Owner owner) {
221	        LocalDate registrationDate = owner.getRegistrationDate();
222	        if (registrationDate == null) {
223	            return false;
